#!/usr/bin/env node
// Generate the per-agent adapter files from the one canonical skill.
//
//   node scripts/sync.mjs           write the generated files
//   node scripts/sync.mjs --check   fail if a committed file differs from what would be written
//
// Sources of truth:
//   skills/visualize-anything/SKILL.md   name and description (frontmatter)
//   package.json                         version, author, licence, repository
// Generated (do not edit by hand):
//   .claude-plugin/plugin.json           Claude Code plugin manifest (also read by Copilot CLI)
//   .claude-plugin/marketplace.json      Claude Code marketplace with this one plugin
//   plugin.json                          portable plugin manifest at the root (Codex)
//   adapters/AGENTS.snippet.md           pointer paragraph for AGENTS.md / copilot-instructions.md
//   adapters/copilot/visualize-anything.prompt.md   VS Code prompt file that points at the skill

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const SKILL = 'skills/visualize-anything/SKILL.md';
const pkg = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'));
const check = process.argv.includes('--check');
const problems = [];

// --- read and check the frontmatter -------------------------------------
const text = readFileSync(join(ROOT, SKILL), 'utf8');
const fm = /^---\n([\s\S]*?)\n---\n/.exec(text);
if (!fm) { console.error(`${SKILL} has no YAML frontmatter`); process.exit(1); }
const meta = {};
for (const line of fm[1].split('\n')) {
  const m = /^([A-Za-z-]+):\s*(.*)$/.exec(line);
  if (!m) { problems.push(`${SKILL}: frontmatter line is not "key: value" on one line: ${line}`); continue; }
  meta[m[1]] = m[2].replace(/^(['"])(.*)\1$/, '$2');
}
// The keys every target accepts. Claude's app upload rejects anything outside this set.
const PORTABLE = ['name', 'description', 'license', 'compatibility', 'metadata', 'allowed-tools'];
for (const k of Object.keys(meta)) if (!PORTABLE.includes(k)) problems.push(`${SKILL}: frontmatter key "${k}" is not portable (allowed: ${PORTABLE.join(', ')})`);
if (meta.name !== 'visualize-anything') problems.push(`${SKILL}: name must equal the directory name "visualize-anything"`);
if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(meta.name ?? '') || (meta.name ?? '').length > 64) problems.push(`${SKILL}: name must be 1-64 characters of a-z, 0-9 and single hyphens`);
if (!meta.description) problems.push(`${SKILL}: description is required`);
else if (meta.description.length > 1024) problems.push(`${SKILL}: description is ${meta.description.length} characters; the Agent Skills limit is 1024`);
if (/[<>]/.test(meta.description ?? '')) problems.push(`${SKILL}: description must not contain < or >`);
if (/: /.test(meta.description ?? '') && !/^['"]/.test(fm[1].split('\n').find((l) => l.startsWith('description:')).slice(12).trim())) {
  problems.push(`${SKILL}: description contains ": " and is not quoted, which is not valid YAML. Rephrase or quote it`);
}

// --- the generated files -------------------------------------------------
const json = (o) => JSON.stringify(o, null, 2) + '\n';
const author = { name: pkg.author.name, url: pkg.author.url };
const manifest = {
  name: meta.name,
  version: pkg.version,
  description: pkg.description,
  author,
  homepage: pkg.homepage,
  repository: pkg.homepage,
  license: pkg.license,
  keywords: pkg.keywords,
};
const GENERATED = `Generated by scripts/sync.mjs from ${SKILL} and package.json. Do not edit; run "npm run sync".`;
const files = {
  '.claude-plugin/plugin.json': json(manifest),
  '.claude-plugin/marketplace.json': json({
    name: meta.name,
    owner: { name: pkg.author.name, url: pkg.author.url },
    metadata: { description: pkg.description, version: pkg.version },
    plugins: [
      {
        name: meta.name,
        source: './',
        description: pkg.description,
        version: pkg.version,
        author,
        homepage: pkg.homepage,
        license: pkg.license,
        keywords: pkg.keywords,
        category: 'learning',
      },
    ],
  }),
  'plugin.json': json({ name: meta.name, version: pkg.version, description: pkg.description, author, homepage: pkg.homepage, license: pkg.license, keywords: pkg.keywords }),
  'adapters/AGENTS.snippet.md': `<!-- ${GENERATED} -->
## Visual explainers (visualize-anything)

When asked to visualize how something works, animate a flow, make a step-by-step or playable
sequence diagram, explain something visually, or build an interactive explainer, use the
\`${meta.name}\` skill: read \`.agents/skills/${meta.name}/SKILL.md\` and follow it exactly.
It has you write the subject as a JSON spec, validate it, and build one self-contained HTML file
with the bundled player. Do not write a custom renderer. Do not use it for charts of numeric data
or for static diagrams with no sequence of steps.
`,
  'adapters/copilot/visualize-anything.prompt.md': `---
description: Build an interactive step-by-step visual explainer of a process, protocol, architecture or algorithm
agent: agent
argument-hint: What should be visualized, e.g. "the TCP three-way handshake"
---
<!-- ${GENERATED} -->
Use the \`${meta.name}\` skill for this request. If the skill is not already loaded, read
\`.github/skills/${meta.name}/SKILL.md\` (or \`.agents/skills/${meta.name}/SKILL.md\`,
or \`.claude/skills/${meta.name}/SKILL.md\`, whichever exists) and follow its workflow exactly:
understand the subject, write the spec, validate, build, check, report.

Subject to visualize: \${input:subject:What should be visualized?}
`,
};

// --- write or compare ----------------------------------------------------
let stale = 0;
for (const [rel, content] of Object.entries(files)) {
  const abs = join(ROOT, rel);
  const current = existsSync(abs) ? readFileSync(abs, 'utf8') : null;
  if (check) {
    const ok = current === content;
    console.log(`${ok ? 'OK  ' : 'STALE'} ${rel}`);
    if (!ok) stale++;
  } else {
    mkdirSync(dirname(abs), { recursive: true });
    if (current !== content) writeFileSync(abs, content);
    console.log(`${current === content ? 'same ' : 'wrote'} ${rel}`);
  }
}
for (const p of problems) console.log(`FAIL ${p}`);
if (!problems.length) console.log(`OK   ${SKILL} frontmatter (description ${meta.description.length}/1024 characters)`);
if (stale) console.log('Adapters are out of date. Run "npm run sync" and commit the result.');
process.exit(stale || problems.length ? 1 : 0);
